@startuml

class Center {
  + Name : string
  + Address : string
}

class Room {
  + RoomNumber : int
  + MaxCapacity : int
}

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Prospect {
}

class Intern {
}

class Session {
  + Date : date
  + StartHour : time
}

class GroupSession {
  + Type : string
}

class IndividualSession {}

Center "1" *-- "1..*" Room
Room "1" -- "0..1" Session

Person --|> Trainer
Person --|> Member
Person --|> Prospect
Trainer --|> Intern

Trainer "1" -- "0..*" GroupSession : supervises
Member "0..*" -- "0..*" Session : participates
Prospect "0..*" -- "0..*" Session : participates
Intern "0..*" -- "0..*" GroupSession : supervises

GroupSession --|> Session
IndividualSession --|> Session

@enduml

